CREATE TABLE `content_translations` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL,
  `locale` varchar(2) COLLATE utf8mb4_unicode_ci NOT NULL,
  `published_slug` varchar(160) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `draft_revision_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `published_revision_id` char(36) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `version` int NOT NULL DEFAULT '0',
  `published_at` datetime(3) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `content_id` (`content_id`,`locale`),
  UNIQUE KEY `locale` (`locale`,`published_slug`),
  CONSTRAINT `content_translations_ibfk_1` FOREIGN KEY (`content_id`) REFERENCES `content_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
